 "content": "from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = []
    for row in grid:
        if all(v == row[0] for v in row):
            out.append(row[:])
        elif background in row:
            out.append([1 if v == background else v for v in row])
        else:
            out.append(row[:])
    return out
